import csv
import io


def _infer(value):
    """Type-infer a single CSV field value."""
    if value in ('null', 'None'):
        return None
    if value == 'true':
        return True
    if value == 'false':
        return False
    # Integers: reject leading zeros (e.g. '007' stays a string), allow
    # optional sign, and reject things like '+'/'-' alone.
    if value.lstrip('+-').isdigit() and len(value.lstrip('+-')) > 1 or (value.isdigit() and len(value) == 1):
        if not (len(value.lstrip('+-')) > 1 and value.lstrip('+-')[0] == '0'):
            try:
                return int(value)
            except ValueError:
                pass
    # Floats: use float() but guard against inf/nan and leading-zero
    # mantissas like '007.5'.
    try:
        f = float(value)
        if value.lower() in ('inf', '-inf', '+inf', 'infinity', '-infinity', '+infinity',
                             'nan', '-nan', '+nan'):
            return value
        stripped = value.lstrip('+-')
        if '.' in stripped or 'e' in stripped.lower():
            mantissa = stripped.lower().split('e')[0]
            int_part = mantissa.split('.')[0]
            if len(int_part) > 1 and int_part[0] == '0':
                return value
            return f
    except ValueError:
        pass
    return value


def parse_csv_typed(csv_string):
    """Parse a CSV string with a header row into a list of typed dicts."""
    reader = csv.reader(io.StringIO(csv_string))
    rows = [row for row in reader if row]  # skip empty rows
    if not rows:
        return []
    header = rows[0]
    result = []
    for row in rows[1:]:
        if not row:
            continue
        record = {}
        for i, key in enumerate(header):
            raw = row[i] if i < len(row) else ''
            record[key] = _infer(raw)
        result.append(record)
    return result
